mapper.select:
SELECT COUNT(DISTINCT p.id)
FROM post p

    INNER JOIN post_tag pt ON p.id = pt.post_id AND pt.tag_id = #{tagId}

WHERE p.is_deleted = 0

    AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))


    AND p.user_id = #{userId}


    AND p.status = #{status}

SELECT p.id, p.user_id as userId, p.title, CASE WHEN LENGTH(p.content) > 100 THEN CONCAT(SUBSTRING(p.content, 1, 100), '...') ELSE p.content END as contentSummary, p.is_anonymous as isAnonymous, p.status, p.view_count as viewCount, p.like_count as likeCount, p.comment_count as commentCount, p.created_at as createdAt FROM post p
INNER JOIN post_tag pt ON p.id = pt.post_id AND pt.tag_id = #{tagId}
WHERE p.is_deleted = 0
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
AND p.user_id = #{userId}
AND p.status = #{status}
ORDER BY p.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT p.id)
FROM post p
INNER JOIN user_post_likes upl ON p.id = upl.post_id AND upl.like_status = 1 AND upl.user_id = #{userId}

    INNER JOIN post_tag pt ON p.id = pt.post_id AND pt.tag_id = #{tagId}

WHERE p.is_deleted = 0

    AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))


    AND p.status = #{status}

SELECT p.id, p.user_id as userId, p.title, CASE WHEN LENGTH(p.content) > 100 THEN CONCAT(SUBSTRING(p.content, 1, 100), '...') ELSE p.content END as contentSummary, p.is_anonymous as isAnonymous, p.status, p.view_count as viewCount, p.like_count as likeCount, p.comment_count as commentCount, p.created_at as createdAt FROM post p INNER JOIN user_post_likes upl ON p.id = upl.post_id AND upl.like_status = 1 AND upl.user_id = #{userId}
INNER JOIN post_tag pt ON p.id = pt.post_id AND pt.tag_id = #{tagId}
WHERE p.is_deleted = 0
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
AND p.status = #{status}
ORDER BY p.created_at DESC LIMIT #{offset}, #{limit}
